-- Create table for managing policy pages content
CREATE TABLE public.policy_pages (
  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  content JSONB NOT NULL DEFAULT '{"content": "", "images": [], "videos": []}'::jsonb,
  meta_description TEXT,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()
);

-- Enable Row Level Security
ALTER TABLE public.policy_pages ENABLE ROW LEVEL SECURITY;

-- Create policies for policy pages
CREATE POLICY "Anyone can view active policy pages" 
ON public.policy_pages 
FOR SELECT 
USING (is_active = true);

CREATE POLICY "Admins can manage policy pages" 
ON public.policy_pages 
FOR ALL 
USING (is_admin());

-- Add trigger for automatic timestamp updates
CREATE TRIGGER update_policy_pages_updated_at
BEFORE UPDATE ON public.policy_pages
FOR EACH ROW
EXECUTE FUNCTION public.update_updated_at_column();

